	m.state = state
	m.rebuildTable()
}

func (m *memoriesModel) setSize(w, h int) {
	m.width = w
	m.height = h
	// Reserve 3 lines for filter bar + detail pane header area
	tableH := h - 3
	if m.showDetail {
		tableH = h / 2
	}
	if tableH < 3 {
		tableH = 3
	}
	m.table.SetWidth(w)
	m.table.SetHeight(tableH)
