   132	func projectSkillGlobs(repoRoot string) []string {
   133		return []string{
   134			filepath.Join(repoRoot, ".claude", "skills", "*", "SKILL.md"),
   135			filepath.Join(repoRoot, ".codex", "skills", "*", "SKILL.md"),
   136		}
   137	}
   138	
   139	func matchingSkillTargets(globs []string, skillName string) ([]FileTarget, error) {
   140		skillName = strings.TrimSpace(skillName)
   141		if skillName == "" {
   142			return nil, errors.New("skill name is required")
   143		}
   144	
   145		var targets []FileTarget
   146		for _, pattern := range globs {
   147			matches, err := filepath.Glob(pattern)
   148			if err != nil {
   149				return nil, fmt.Errorf("glob skill targets: %w", err)
   150			}
   151			for _, match := range matches {
   152				if filepath.Base(filepath.Dir(match)) != skillName {
   153					continue
   154				}
   155				targets = append(targets, FileTarget{Path: match})
   156			}
   157		}
   158		if len(targets) == 0 {
   159			return nil, fmt.Errorf("no skill targets found for %q", skillName)
   160		}
   161		return targets, nil
   162	}
