	b.WriteString("\n")
	b.WriteString(m.styles.render(m.styles.title, "Wizard"))
	b.WriteString("\n")
	b.WriteString("  w  open wizard    up/down  choose    enter  next/confirm    esc  back/close\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Injection"))
	b.WriteString("\n")
